function resolveBrickCollisions(state, dt, prevX, prevY) {
  const { ball, bricks } = state;
  let collided = false;

  for (const brick of bricks) {
    if (!brick.alive) continue;

    // Tunnelling: Check if the ball's path intersects the brick.
    // Simple check: does the bounding box of the movement overlap the brick?
    const minX = Math.min(prevX, ball.x) - ball.r;
    const maxX = Math.max(prevX, ball.x) + ball.r;
    const minY = Math.min(prevY, ball.y) - ball.r;
    const maxY = Math.max(prevY, ball.y) + ball.r;

    if (maxX < brick.x || minX > brick.x + brick.w || maxY < brick.y || minY > brick.y + brick.h) {
      continue;
    }

    // Now we have a potential collision.
    // We can use the "smaller penetration" rule if it's currently overlapping.
    // But for a sweep test, we should find the exact time of entry.

    if (collides(ball, brick)) {
      collided = true;

      // 1. Per face / Corner: Smaller penetration
      const overlapX = Math.min(ball.x + ball.r - brick.x, brick.x + brick.w - (ball.x - ball.r));
      const overlapY = Math.min(ball.y + ball.r - brick.y, brick.y + brick.h - (ball.y - ball.r));

      if (overlapX < overlapY) {
        // Side hit
        ball.vx *= -1;
        // Push out
        if (ball.x < brick.x + brick.w / 2) ball.x = brick.x - ball.r;
        else ball.x = brick.x + brick.w + ball.r;
      } else if (overlapY < overlapX) {
        // Top/Bottom hit
        ball.vy *= -1;
        // Push out
        if (ball.y < brick.y + brick.h / 2) ball.y = brick.y - ball.r;
        else ball.y = brick.y + brick.h + ball.r;
      } else {
        // Corner hit
        ball.vx *= -1;
        ball.vy *= -1;
        // Push out (this is tricky for corners, but let's just use the axes)
        if (ball.x < brick.x + brick.w / 2) ball.x = brick.x - ball.r;
        else ball.x = brick.x + brick.w + ball.r;
        if (ball.y < brick.y + brick.h / 2) ball.y = brick.y - ball.r;
        else ball.y = brick.y + brick.h + ball.r;
