edits.newText:
test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

import { resolveBrickCollisions } from './neon.js';

test('resolveBrickCollisions: top hit flips vy', () => {
  const state = createState(1);
  state.ball = { x: 100, y: 50, r: 7, vx: 0, vy: -200 }; // moving up
  state.bricks = [{ x: 80, y: 40, w: 40, h: 20, alive: true }];
  resolveBrickCollisions(state, 1 / 60);
  assert.ok(state.ball.vy > 0, 'vy should flip to positive');
  assert.equal(state.bricks[0].alive, false);
});

test('resolveBrickCollisions: side hit flips vx', () => {
  const state = createState(1);
  state.ball = { x: 70, y: 50, r: 7, vx: 200, vy: 0 }; // moving right
  state.bricks = [{ x: 80, y: 40, w: 40, h: 20, alive: true }];
  resolveBrickCollisions(state, 1 / 60);
  assert.ok(state.ball.vx < 0, 'vx should flip to negative');
  assert.equal(state.bricks[0].alive, false);
});

test('resolveBrickCollisions: corner hit flips both', () => {
  const state = createState(1);
  // Position ball so it hits the top-left corner exactly
  state.ball = { x: 73, y: 33, r: 7, vx: 200, vy: -200 };
  state.bricks = [{ x: 80, y: 40, w: 40, h: 20, alive: true }];
  resolveBrickCollisions(state, 1 / 60);
  assert.ok(state.ball.vx < 0 && state.ball.vy > 0, 'both vx and vy should flip');
});

test('resolveBrickCollisions: prevents tunnelling', () => {
  const state = createState(1);
  state.ball = { x: 100, y: 100, r: 7, vx: 0, vy: -2000 }; // very fast
  state.bricks = [{ x: 80, y: 50, w: 40, h: 20, alive: true }];
  // In one step, ball moves from 100 to 100 - 2000/60 = 66.6
  // Brick is at 50, height 20. Ball radius 7.
  // Bounding box: 50 to 70. Ball range: 66.6 to 100.
  // It should hit.
  resolveBrickCollisions(state, 1 / 60);
  assert.equal(state.bricks[0].alive, false, 'ball should not tunnel through brick');
});

test('resolveBrickCollisions: handles neighbours (one bounce only)', () => {
  const state = createState(1);
  state.ball = { x: 100, y: 50, r: 7, vx: 0, vy: -200 };
  state.bricks = [
    { x: 80, y: 40, w: 40, h: 20, alive: true },
    { x: 120, y: 40, w: 40, h: 20, alive: true },
  ];
  // Ball is between two bricks, but should only hit one if it's precisely placed
  // or if it's a sweep test, it hits the first one.
  resolveBrickCollisions(state, 1 / 60);
  const flippedOnce = (state.ball.vy > 0); 
  // If it hit both and flipped twice, it would be vy < 0 again.
  assert.ok(flippedOnce, 'should have bounced exactly once');
});

function belowField() {
  return 500;
}

